INSERT INTO language_concept
(
    language_id,
    concept_id
)
SELECT
    language_id,
    id
FROM concept
WHERE
    language_id = 'pt-BR';

INSERT INTO concept_dependency
(
    concept_id,
    prerequisite_id
)
SELECT
    recall.id,
    recognition.id
FROM concept recall
JOIN concept recognition
    ON recognition.language_id = recall.language_id
    AND recognition.topic_id = recall.topic_id
    AND recognition.skill_id = 'word_recognition'
WHERE
    recall.language_id = 'pt-BR'
    AND recall.skill_id = 'word_recall';
